// Bugünün cevaplarını filtrele ve analiz et
const today = new Date();
today.setHours(0, 0, 0, 0);

const user = $node['Kullanıcıları Böl'].json;
const allAnswers = $node['Cevapları Getir'].json.data || [];

// Bu kullanıcının bugünkü cevaplarını filtrele
const todayAnswers = allAnswers.filter(answer => {
  const answerDate = new Date(answer.answered_date);
  answerDate.setHours(0, 0, 0, 0);
  return answer.user_id === user.id && answerDate.getTime() === today.getTime();
});

// Eğer bugün soru çözmediyse atla
if (todayAnswers.length === 0) {
  return null;
}

// İstatistikleri hesapla
const correctAnswers = todayAnswers.filter(a => a.is_correct).length;
const wrongAnswers = todayAnswers.length - correctAnswers;
const successRate = Math.round((correctAnswers / todayAnswers.length) * 100);

// Ders bazlı analiz
const subjectStats = {};
todayAnswers.forEach(answer => {
  if (!subjectStats[answer.subject]) {
    subjectStats[answer.subject] = { total: 0, correct: 0 };
  }
  subjectStats[answer.subject].total++;
  if (answer.is_correct) {
    subjectStats[answer.subject].correct++;
  }
});

// En iyi ve en kötü ders
const subjectRates = Object.entries(subjectStats).map(([subject, stats]) => ({
  subject,
  rate: Math.round((stats.correct / stats.total) * 100),
  total: stats.total
}));

subjectRates.sort((a, b) => b.rate - a.rate);

return {
  json: {
    user: {
      id: user.id,
      username: user.username,
      full_name: user.full_name,
      email: user.email
    },
    stats: {
      total: todayAnswers.length,
      correct: correctAnswers,
      wrong: wrongAnswers,
      successRate: successRate
    },
    subjectStats: subjectRates,
    bestSubject: subjectRates[0]?.subject || 'N/A',
    worstSubject: subjectRates[subjectRates.length - 1]?.subject || 'N/A',
    date: today.toISOString().split('T')[0]
  }
};

const data = $input.item.json;

// Motivasyon mesajı
let motivationMessage = '';
if (data.stats.successRate >= 80) {
  motivationMessage = '🎉 Mükemmel performans! Böyle devam et!';
} else if (data.stats.successRate >= 60) {
  motivationMessage = '💪 Harika gidiyorsun! Biraz daha çalışarak hedefe ulaşacaksın!';
} else if (data.stats.successRate >= 40) {
  motivationMessage = '📚 İyi bir başlangıç! Eksik konuları tekrar etmeyi unutma.';
} else {
  motivationMessage = '🔥 Pes etme! Her hata bir öğrenme fırsatı. Yarın daha iyisini yapacaksın!';
}

// Ders bazlı analiz tablosu
let subjectTable = '';
data.subjectStats.forEach(subject => {
  const emoji = subject.rate >= 70 ? '✅' : subject.rate >= 50 ? '⚠️' : '❌';
  subjectTable += `${emoji} ${subject.subject}: ${subject.total} soru, %${subject.rate} başarı\n`;
});

// E-posta içeriği
const emailContent = `
Merhaba ${data.user.full_name},

Bugünkü performans özetin hazır! 📊

═══════════════════════════════
GÜNLÜK İSTATİSTİKLER (${data.date})
═══════════════════════════════

📝 Toplam Soru: ${data.stats.total}
✅ Doğru: ${data.stats.correct}
❌ Yanlış: ${data.stats.wrong}
📈 Başarı Oranı: %${data.stats.successRate}

${motivationMessage}

═══════════════════════════════
DERS BAZLI ANALİZ
═══════════════════════════════

${subjectTable}
🏆 En İyi Ders: ${data.bestSubject}
📌 Geliştirilmesi Gereken: ${data.worstSubject}

═══════════════════════════════
ÖNERİLER
═══════════════════════════════

${data.stats.successRate < 70 ? `• ${data.worstSubject} dersinde konu tekrarı yapmanı öneririm\n` : ''}• Hergün düzenli soru çözmeye devam et
• Yanlış yaptığın soruların çözümlerini incele
• Zayıf olduğun konulara daha fazla zaman ayır

═══════════════════════════════

Yarın da soru çözmeye devam etmeyi unutma! 💪

İyi çalışmalar,
YKS KAFA Ekibi

---
Bu e-posta otomatik olarak gönderilmiştir.
`;

return {
  json: {
    ...data,
    emailContent: emailContent
  }
};
